    "description": "Путешествие Арка — геймера, застрявшего в теле могущественного рыцаря-скелета, — продолжается. Несмотря на жуткий облик, скрытый под тяжёлой бронёй, этот необычный наёмник обладает добрым сердцем и готов прийти на помощь любому, кто попал в беду. Вместе с верным питомцем По́нтой он уверенно прокладывает себе путь через неизведанные земли нового мира.\r\nНа этот раз его главная цель — помочь эльфийской воительнице Ариа́нне освободить её соплеменников из рабства. Впереди команду ждёт опасный поход вглубь человеческих королевств, столкновение с теневыми работорговцами и заговоры знати. Противникам остаётся лишь посочувствовать, ведь в бой вступает скрытый паладин с максимальным уровнем прокачки.",
