    "description": "Арнольд — седьмой принц империи Эдразия. Он никогда не стремился к власти и снискал славу ленивого бездаря, который во всём уступает своему брату-близнецу Леонарду. Однако за этой ширмой скрывается один из пяти авантюристов SS-класса, известный как Сильвер, которому подвластна даже древняя магия.\r\nА тем временем битва за престол набирает обороты, и, чтобы защитить своих близких, Арнольд начинает действовать. Оставаясь в тени, он делает всё, чтобы его брат-близнец стал следующим императором. Сможет ли Арнольд и дальше скрывать свою силу, и ждёт ли его беззаботная жизнь, о которой он так мечтает?",
