    "media_type": "anime-series",
    "source": "anilibria",
    "description": "По всему миру внезапно появились загадочные гробницы. В каждой из них хранилась реликвия, наделяющая своего владельца сверхъестественными способностями.\r\nГлавный герой истории — Джухон Со — исследователь, раскопщик и охотник за гробницами. Преданный собственным работодателем, он оказывается на волосок от гибели, как вдруг переносится на 15 лет в прошлое, в то время, когда ни реликвий, ни гробниц ещё не существовало.\r\nИ теперь, сжигаемый жаждой мести, Джухон сделает всё, чтобы стать Королём Расхитителей Гробниц!",
