    "description": "Страдая от редкой и неизлечимой болезни, вызывающей пугающие изменения в теле, девушка по имени Куро́е Акаи́ши проводит школьные дни, сторонясь одноклассников — особенно первого красавчика класса Ара́ты Мина́ми и его свиты.\r\nНо когда Ара́та начинает с раздражающей регулярностью заставлять её сердце замирать, Курое обнаруживает, что её недуг таит в себе большой — нет, ОГРОМНЫЙ — секрет: влюблённость буквально превращает её в чудовище!",
