    "media_type": "anime-series",
    "source": "anilibria",
    "description": "Жизнь Юри Су́дзуки переворачивается, когда магия утягивает её из современной Японии в Хеттскую империю бронзового века. Оказавшись в прошлом, девушка узнаёт, что коварная царица На́кия жаждет принести её в жертву ради захвата власти. Так что пока дома Юри ищет полиция, здесь на неё начинается смертельная охота.\r\nОт ритуальной казни девушку спасает вмешательство принца Кайли, а знания истории и металлургии помогают ей закрепиться в обществе древнего мира.\r\nПроявив отвагу в боях, она завоёвывает уважение суровых воинов, которые начинают почитать обычную девчонку в джинсах как богиню войны Иштар.",
    "air_timestamp": 1790888400000
