    "description": "Зловещая организация «Шокер», которая кроме Японии, расположила свои подразделения по всему миру, стремится завоевать мир, действуя террористическими методами. Для этого она создаёт ужасных монстров и киборгов. Однако один из киборгов — бывший студент Хонго Такеши, сбегает прежде чем ему были промыты мозги, и приняв имя Камен Райдер (Наездник в маске), начинает сражаться с «Шокером». Когда позже Хонго Такеши вынужден уехать из Японии, он оставляет вместо себя Хайято Ичимонджи, который становится Камен Райдером 2. «Шокер» и Райдеры ведут войну не на жизнь, а на смерть.",
