    "description": "Смерть — не всегда конец. Иногда она становится паузой, в которой чувства и воспоминания не позволяют душе уйти. Те, кто не смог отпустить прошлое, остаются среди живых, постепенно теряя себя и превращаясь в опасных духов.\r\n\r\nЧтобы поддерживать порядок, Японская федерация ангелов разыскивает такие души и устраняет связанные с ними аномалии. Для большинства её сотрудников духи — лишь системный сбой, который необходимо быстро устранить. Но вспыльчивый и добродушный Тэцуо Тамба и его любопытный капитан Мисаки Куроганэ по-прежнему видят в каждом из них человека, неспособного сделать последний шаг в одиночку.\r\n\r\nИх внимательный подход противоречит жёстким правилам федерации, требующей быстрых и строго регламентированных действий. Нарушая протоколы, Тэцуо и Мисаки всё чаще оказываются перед выбором между приказами и собственными принципами.\r\n\r\nТеперь каждое задание становится для них испытанием: исполнить долг или рискнуть всем ради тех, кого они должны были лишь упокоить.",
