    "media_type": "anime-series",
    "source": "anilibria",
    "description": "В борьбе за руку и сердце наследного принца завистливая Кэйгэцу решается на отчаянный ритуал и меняется телами с главной претенденткой на роль следующей императрицы, придворной дамой Рэйрин. Но цена запретной магии оказывается слишком высокой: оказывается, что тело Рэйрин неизлечимо больно, и теперь Кэйгэцу балансирует на грани жизни и смерти. А сама Рэйрин, оказавшись на месте отверженной изгнанницы, вынуждена отвечать за преступления соперницы. \r\nСудьбы девушек всё теснее переплетаются: чтобы выжить, им придётся действовать сообща. Смогут ли они преодолеть ненависть и вместе раскрыть заговоры, таящиеся под благопристойным обликом дворца?",
