    "description": "Ирума — самый обыкновенный мальчишка: он любит веселиться и легко заводит новых друзей. Он бы и рад наслаждаться привычными школьными буднями, да только учебное заведение ему досталось специфическое — исключительно для демонов! Несмотря на то, что Ирума человек, он всё равно стал главной звездой и любимцем класса. Впрочем, оно и неудивительно, когда самый могущественный демон — твой новоиспечённый дедуля, который души в тебе не чает. \r\nОднако школьная жизнь у Ирумы не становится легче, ведь всему классу под угрозой отчисления выставили требование получить ранг Далет! И единственный шанс достичь цели — хорошо выступить на музыкальном фестивале. Звучит просто, но у демонов в любом деле припрятаны свои сюрпризы!",
