    "description": "После одного из самых тяжёлых испытаний в своей жизни Майн принимает непростое решение: она решает попрощаться со своей семьёй и друзьями и начать новую жизнь в качестве приёмной дочери эрцгерцога Эренфеста.\r\nНо жизнь в знатном обществе не так проста, как кажется простолюдинам: жёсткие нормы и правила этикета, обучение магии, а также обязанности Архиепископа давят на семилетнюю девочку непосильным грузом. Однако награда того стоит: ведь она получает ключ к настоящей сокровищнице — библиотеке, доступной только высшим слоям общества. Так что круто изменить свою жизнь — это малая плата за возможность изменить весь мир.",
