    "description": "Каждые четыре века рождаются близнецы, разделённые днём и ночью, которым самой судьбой уготовано стать повелителями цугаев. Цугаи — существа-противоположности, невидимые для обычных людей: \"божества\" и \"ёкаи\".\r\nИх сила находится за гранью человеческого понимания, и именно поэтому вновь родившиеся близнецы — Аса и Юру — становятся целью для множества преступных группировок. Но даже лишившись спокойного детства из-за своего проклятия, герои не думают сдаваться. И пусть впереди их ждут бесконечные сражения, убийства и предательства, вместе со своими цугаями они обязательно бросят вызов своей несправедливой судьбе.",
